body.g:evaluate:
var out='';
if(!gs.hasRole('admin')){out='<p>Administrator role required for this synthetic lab.</p>';}
else{
 var count=0,ready=0,held=0,rows='';
 function esc(v){return GlideStringUtil.escapeHTML(String(v||''));}
 function rupees(v){if(v===null||v==='')return '—';return 'INR '+(Number(v)/100).toFixed(2);}
 var g=new GlideRecord('u_jewel_exchange_case');g.addQuery('correlation_id','STARTSWITH','JEX-');g.orderBy('correlation_id');g.query();
 while(g.next()){count++;var status=g.getValue('u_triage');if(status==='HOLD')held++;else ready++;rows+='<tr><td><a href="u_jewel_exchange_case.do?sys_id='+esc(g.getUniqueValue())+'">'+esc(g.getValue('correlation_id'))+'</a></td><td>'+esc(g.getValue('u_original_item'))+'</td><td>'+rupees(g.getValue('u_claimed_paise'))+'</td><td>'+rupees(g.getValue('u_expected_paise'))+'</td><td class="'+(status==='HOLD'?'hold':'ready')+'">'+esc(status)+'</td><td>'+esc(g.getValue('u_reasons')||'Human approval required')+'</td></tr>';}
 var tasks=new GlideAggregate('task');tasks.addQuery('correlation_id','STARTSWITH','JEXREVIEW-');tasks.addAggregate('COUNT');tasks.query();var n=tasks.next()?tasks.getAggregate('COUNT'):'0';
 out='<header><small>SERVICENOWJYO · DEVELOPER INSTANCE</small><h1>Jewellery Finance Controls</h1><p>Original purchase validation · policy credit · exception review</p></header><main><div class="notice">SYNTHETIC PDI LAB · Independent learning project · Not an Emmadi deployment · No credit issued</div><section class="metrics"><article><b>'+count+'</b>Persisted synthetic claims</article><article><b>'+ready+'</b>Ready for human approval</article><article><b>'+held+'</b>Held for review</article><article><b>'+n+'</b>Human-review tasks</article></section><section><h2>Live platform results</h2><p>Read directly from Jewellery Exchange Case records. Amounts shown in INR; stored as integer paise.</p><table><thead><tr><th>Case</th><th>Original item</th><th>Claimed credit</th><th>Expected credit</th><th>Triage</th><th>Review reason</th></tr></thead><tbody>'+rows+'</tbody></table></section><section><h2>How it works</h2><p>Before-insert Business Rule → Script Include → protected result snapshot → after-insert human-review task</p><p><strong>Whole-item demo policy:</strong> eligible original purchase × 55%. Human review is required for every case.</p><p><strong>Duplicate handling:</strong> sequential platform intake holds the later claim. Local batch mode holds both duplicate claims (4 ready / 8 held).</p><p><strong>Time goal:</strong> triage in minutes after import. Business handling-time savings have not been measured.</p></section></main>';
}
out;
